% Temperature conversion: Fahrenheit to Kelvin
while true
    % Read input temperature in Fahrenheit
    F = input('Enter temperature in Fahrenheit: ');

    % Convert Fahrenheit to Celsius
    C = (F - 32) * 5/9;

    % Convert Celsius to Kelvin (absolute temperature)
    K = C + 273.15;

    % Display the result
    fprintf('Temperature in Fahrenheit : %.2f F\n', F);
    fprintf('Temperature in Celsius    : %.2f C\n', C);
    fprintf('Absolute Temperature (K)  : %.2f K\n', K);

    % Break after one conversion as required
    break;
end

% Gauss Elimination Method for 4x4 system of linear equations
% Define coefficient matrix A and RHS vector b
% (Replace with actual values as needed)
A = [2  1 -1  1;
     4  3 -1  2;
    -2  1  3 -1;
     1  2  1  3];

b = [5; 12; 1; 10];

n = length(b);  % number of equations

% Form augmented matrix [A | b]
Aug = [A, b];

% ---- FORWARD ELIMINATION ----
for k = 1:n-1
    for i = k+1:n
        % Compute elimination factor
        factor = Aug(i,k) / Aug(k,k);
        % Eliminate the k-th column in row i
        Aug(i,:) = Aug(i,:) - factor * Aug(k,:);
    end
end

% Separate updated A and b from augmented matrix
A_upper = Aug(1:n, 1:n);
b_upper = Aug(1:n, n+1);

% ---- BACK SUBSTITUTION ----
x = zeros(n, 1);  % initialize solution vector

% Solve for last variable
x(n) = b_upper(n) / A_upper(n,n);

% Solve remaining variables from bottom to top
for i = n-1:-1:1
    x(i) = (b_upper(i) - A_upper(i, i+1:n) * x(i+1:n)) / A_upper(i,i);
end

% Display the solution
fprintf('Solution by Gauss Elimination:\n');
for i = 1:n
    fprintf('  x%d = %.4f\n', i, x(i));
end

