% Method 1: hold on / hold off
x = 0:0.1:2*pi;           % x values from 0 to 2*pi
figure(1);
plot(x, sin(x), 'r-');    % plot sine curve in red
hold on;                   % keep current plot
plot(x, cos(x), 'b--');   % add cosine in blue dashed
hold off;                  % release hold
legend('sin(x)', 'cos(x)');
title('Method 1: hold on/off');
xlabel('x');  ylabel('y');  grid on;

% Method 2: Multiple datasets in one plot call
figure(2);
plot(x, sin(x), 'r-', x, cos(x), 'b--');  % all in one line
legend('sin(x)', 'cos(x)');
title('Method 2: Single plot() call');
grid on;

% Method 3: subplot for side-by-side panels
figure(3);
subplot(2,1,1);           % top panel
plot(x, sin(x), 'r-');
title('sin(x)');
subplot(2,1,2);           % bottom panel
plot(x, cos(x), 'b-');
title('cos(x)');

% Parametric cone: x=r*cos(t), y=r*sin(t), z=4r
% Define parameter ranges
theta = linspace(0, 2*pi, 60);  % angle from 0 to 2*pi
r     = linspace(0, 2, 30);     % radius from 0 to 2

% Create 2D parameter grid
[T, R] = meshgrid(theta, r);

% Compute x, y, z from parametric equations
X = R .* cos(T);  % x = r*cos(theta)
Y = R .* sin(T);  % y = r*sin(theta)
Z = 4 * R;        % z = 4*r

% Plot in same figure with 4 subplots
figure;

% 3D surface
subplot(2,2,1);
surf(X, Y, Z);           % 3D surface plot
title('3D Parametric Surface');
xlabel('X');  ylabel('Y');  zlabel('Z');
colorbar;

% XY projection (top view)
subplot(2,2,2);
plot(X(:), Y(:), 'b.');  % scatter all (x,y) points
title('XY Projection (Top View)');
xlabel('X');  ylabel('Y');  axis equal;  grid on;

% YZ projection (front view)
subplot(2,2,3);
plot(Y(:), Z(:), 'r.');  % scatter all (y,z) points
title('YZ Projection (Front View)');
xlabel('Y');  ylabel('Z');  grid on;

% ZX projection (side view)
subplot(2,2,4);
plot(Z(:), X(:), 'g.');  % scatter all (z,x) points
title('ZX Projection (Side View)');
xlabel('Z');  ylabel('X');  grid on;

% Part i) & ii) Data fitting with 5th order polynomial
% Given data
X = [0, 0.6, 0.9, 1.2, 2.4, 3.6, 4.8, 6.0, 7.2, 8.4, 9.6, 10.8, 12.0, 13.2, 14.4];
Y = [0, 1.16, 1.18, 1.19, 1.24, 1.48, 1.92, 3.12, 4.14, 5.34, 6.22, 7.10, 8.34, 9.50, 10.80];

% Part ii) Fit with 5th order polynomial
p = polyfit(X, Y, 5);  % returns 6 coefficients for degree-5 polynomial

fprintf('5th order polynomial coefficients:\n');
fprintf('p = [%.4f  %.4f  %.4f  %.4f  %.4f  %.4f]\n', p(1),p(2),p(3),p(4),p(5),p(6));

% Evaluate polynomial over smooth range for plotting
X_fit = linspace(0, 15, 200);   % smooth x range
Y_fit = polyval(p, X_fit);       % compute polynomial values

% Plot original data and polynomial fit
figure;
plot(X, Y, 'ro', 'MarkerSize', 8);   % original data points
hold on;
plot(X_fit, Y_fit, 'b-', 'LineWidth', 2);  % polynomial fit curve
hold off;
legend('Data', '5th Order Polynomial Fit');
title('5th Order Polynomial Curve Fitting');
xlabel('X');  ylabel('Y');  grid on;

% Calculate residuals to assess fit quality
Y_pred = polyval(p, X);       % predicted values at data points
residual = Y - Y_pred;        % difference from actual
fprintf('Max residual error: %.4f\n', max(abs(residual)));

% Demonstration of polynomial functions
% Define polynomial: p(x) = 3x^3 + 2x^2 - 5x + 1
p = [3, 2, -5, 1];

% i) polyval: evaluate polynomial at x=2
val = polyval(p, 2);            % p(2) = 23
fprintf('polyval at x=2: %.2f\n', val);

% ii) roots: find zeros of x^2 - 3x + 2
p2 = [1, -3, 2];               % x^2 - 3x + 2
r = roots(p2);                  % roots: x=1 and x=2
disp('Roots of x^2-3x+2:');  disp(r);

% iii) conv: multiply (x+2) * (x-3)
p3 = [1, 2];                   % x+2
p4 = [1, -3];                  % x-3
product = conv(p3, p4);        % result: x^2 - x - 6
disp('conv([1,2],[1,-3]):');   disp(product);

% iv) deconv: divide x^2-x-6 by x+2
p5 = [1, -1, -6];              % x^2 - x - 6
[q, rem] = deconv(p5, p3);    % divide by (x+2)
disp('Quotient of deconv:');   disp(q);
disp('Remainder:');            disp(rem);

% v) polyder: differentiate 3x^3 + 2x^2 - 5x + 1
dp = polyder(p);               % result: 9x^2 + 4x - 5
disp('polyder([3,2,-5,1]):');  disp(dp);
